#include <stdio.h>

struct Team {
    const char *name;
    int points;
};

int main() {
    struct Team t[] = {{"Lions", 12}, {"Tigers", 30}, {"Bears", 21}};
    for (int i = 0; i < 2; i++) {
        for (int j = 0; j < 2 - i; j++) {
            if (t[j].points < t[j + 1].points) {
                struct Team temp = t[j];
                t[j] = t[j + 1];
                t[j + 1] = temp;
            }
        }
    }
    for (int i = 0; i < 3; i++) {
        printf("%s %d\n", t[i].name, t[i].points);
    }
    return 0;
}
